"""Real browser controls with explicit checkpoint fixtures; not full campaign clears."""
import json
from playwright.sync_api import sync_playwright
from browser_support import ROOT, launch
from story_browser_server import story_base_url
OUT=ROOT/'_local/reports/evidence-quests';BASE=story_base_url();checks=[];errors=[]
SETUP='''id=>{const a=HonroApp;a.close();a.stopBattle();const p=HONRO_TOOLS.fresh();for(let i=1;i<id;i++)p.cleared[i]={visits:1};p.recruited=['archer','mage','knight','occultist'];p.party=[...p.recruited];p.settings.sound=false;p.settings.music=false;a.profile=p;a.normalProfile=p;a.launch(id);for(let i=0;a.dialogue&&i<100;i++)HonroStory.finish(a);a.turnNotice=null;document.getElementById('turn-banner').hidden=true;a.lastTurnNotice=`${a.engine.b.round}:player`;return !!a.engine.b.honroEvidenceRevision;}'''
with sync_playwright() as p:
 browser=launch(p)
 for mobile in [False,True]:
  tag='mobile' if mobile else 'desktop';ctx=browser.new_context(viewport={'width':390,'height':844} if mobile else {'width':1440,'height':900},is_mobile=mobile,has_touch=mobile);page=ctx.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
  for before in [True,False]:
   page.goto(BASE+('/_local/reports/evidence-quests/before.html' if before else '/HONRO.html'));page.wait_for_function('window.HonroApp');assert page.evaluate(SETUP,30)==(not before)
   page.evaluate('''()=>{const a=HonroApp,b=a.engine.b,m=b.honroMarkers.find(m=>m.id==='transport-map');Object.assign(a.scene,{x:m.x,y:m.y-100,scale:1,manual:true,goalFocus:null,focusUntil:0});}''');page.wait_for_timeout(180);page.screenshot(path=str(OUT/f'{"before" if before else "after"}-{tag}-30-world.png'))
   result=page.evaluate('''()=>{const a=HonroApp,e=a.engine,b=e.b,m=b.honroMarkers.find(m=>m.id==='transport-map');Object.assign(e.active,{x:m.x,y:m.y,vx:0,vy:0,airborne:false,jumping:false});a.actorBoundary=b.active;a.turnNotice=null;let ok;if(b.honroEvidenceRevision){HonroAct3.tick(a,0);ok=!!b.honroState.act3.done['transport-map'];}else ok=HonroAct3.use(a,m);if(!a.dialogue){e.active.acted=true;b.honroState.actorTurnSerial=(b.honroState.actorTurnSerial||0)+1;}a.startQueuedStory();return {ok,done:!!b.honroState.act3.done['transport-map'],docs:a.profile.honroEvidenceDocuments?.length||0};}''');print(tag,before,result,flush=True);assert result['ok'] and result['done'],result
   page.wait_for_selector('#dialogue-root [role="dialog"]');page.wait_for_timeout(180);page.screenshot(path=str(OUT/f'{"before" if before else "after"}-{tag}-30-reading.png'))
   if before:assert page.locator('.story-document').count()==1;continue
   assert page.locator('.story-document').count()==0
   assert result['docs']==1
   page.evaluate('''()=>{const a=HonroApp;for(let i=0;a.dialogue&&i<100;i++)HonroStory.finish(a);HonroStory.journal(a);}''');page.locator('[data-story-tool="evidence-read:0"]').click();page.wait_for_selector('.story-document');assert '저문골 → 무명사: 시신·금속' in page.locator('#story-line').inner_text();page.locator('[data-story-tool="document-zoom"]').click();assert page.locator('.document-enlarged').count()==1;assert page.locator('.story-document p').first.evaluate('(e)=>getComputedStyle(e).color')=='rgb(41, 46, 41)'
   state=page.evaluate('JSON.stringify({b:HonroApp.engine.b,docs:HonroApp.profile.honroEvidenceDocuments})');page.wait_for_timeout(350);assert state==page.evaluate('JSON.stringify({b:HonroApp.engine.b,docs:HonroApp.profile.honroEvidenceDocuments})'),'read-only modal freezes battle';page.wait_for_timeout(180);page.screenshot(path=str(OUT/f'after-{tag}-optional-map.png'))
   page.keyboard.press('Tab');page.keyboard.press('Escape');assert page.locator('#modal.open').count()==0
   # An already completed observation cannot complete again.
   assert page.evaluate('''()=>{const a=HonroApp,b=a.engine.b,n=b.honroState.act3.checkpoints.length;a.actorBoundary=b.active;HonroAct3.tick(a,0);return b.honroState.act3.checkpoints.length===n;}''')
  for id in [17,24,27,28,29,23]:
   assert page.evaluate(SETUP,id)
   result=page.evaluate('''id=>{const a=HonroApp,e=a.engine,b=e.b,A=id<21?HonroAct2:HonroAct3;for(const u of b.units)if(u.side===1){u.dead=true;u.hp=0;}a.checkMission=()=>false;a.turnNotice=null;a.actorBoundary=b.active;const mem=A.memory(b),steps=A.steps(b);if(id===17){for(const s of steps.slice(0,4))mem.done[s.id]=true;mem.holds={'hold-hoist':{progress:5,spawned:10}};A.tick(a,0);return {ok:mem.done.notes&&mem.done['clear-lift'],keys:mem.checkpoints.map(q=>q.id)};}if(id===24){mem.done['family-crest']=mem.done['shrine-seal']=true;const s=steps.find(s=>s.id==='land-register');A.tick(a,0);if(mem.done[s.id])return {ok:false};for(const [mark,classes]of [['split-route-a',['archer','mage']],['split-route-b',['knight','occultist']]]){const m=b.honroMarkers.find(m=>m.id===mark);for(const cls of classes)Object.assign(b.units.find(u=>u.side===0&&u.cls===cls),{x:m.x,y:m.y});A.tick(a,0);}return {ok:mem.done[s.id],routes:b.honroState.evidenceEntrances};}if(id===27){const m=b.units.find(u=>u.side===0&&u.cls==='mage'),c=b.honroMap.act3.crossings[0];for(const [i,u]of b.units.filter(u=>u.side===0).entries())Object.assign(u,{x:c.from.x-70+i*70,y:c.from.y,vx:0,vy:0,airborne:false,jumping:false,acted:false,focus:u.maxFocus});b.active=m.id;b.phase='aim';b.side=0;b.wind=0;m.loadout=['M01','M03','M06','M09'];m.ranks.M09=1;let shot;for(let angle=10;angle<=86&&!shot;angle+=2)for(let power=.7;power<=1;power+=.025){const hit=e.predict(m,HONRO_CORE.SKILLS.M09,angle,power);if(hit.x>c.landing.left+35&&hit.x<c.landing.right-35&&Math.abs(hit.y-c.landing.y)<15){shot={angle,power};break;}}if(!shot)return {ok:false,reason:'no real M09 aim'};const fired=e.fire('M09',shot.angle,shot.power);e.checkEnd=()=>false;for(let i=0;i<3000&&!(b.stakes||[]).length;i++)e.tick(1/120);a.actorBoundary=b.active;A.tick(a,0);return {ok:fired&&mem.done['depot-route-ledger'],stakes:b.stakes?.length,shot,void:b.honroAct3Void?.state};}if(id===28){mem.done['fire-screen']=mem.done['water-release']=mem.done['party-reunion']=true;const marker=b.honroMarkers.find(m=>m.id==='petition-record');Object.assign(e.active,{x:marker.x,y:marker.y});const used=A.use(a,marker);for(let i=0;a.dialogue&&i<100;i++)HonroStory.finish(a);A.tick(a,0);return {ok:used&&mem.done['closure-order']&&mem.done['suppression-order'],keys:mem.checkpoints.map(q=>q.id)};}if(id===29){mem.holds={'old-seal':{progress:2,spawned:2}};A.tick(a,0);return {ok:mem.done['old-seal']&&mem.done['hyeonmuk-letter']};}if(id===23){const marker=b.honroMarkers.find(m=>m.id==='dispatch-bundle'),u=b.units.find(u=>u.id==='act3-carrier');Object.assign(e.active,{x:u.x-80,y:u.y});const used=A.use(a,marker);for(let i=0;a.dialogue&&i<100;i++)HonroStory.finish(a);A.tick(a,0);return {ok:used&&mem.done['carrier-start']&&mem.escorts[u.id]?.started};}}''',id)
   assert result['ok'],(id,result)
   page.wait_for_timeout(180);page.screenshot(path=str(OUT/f'after-{tag}-stage{id}.png'));checks.append({'device':tag,'stage':id,**result})
  ctx.close()
 browser.close()
assert not errors,errors
(OUT/'browser.json').write_text(json.dumps({'passed':True,'checks':checks,'errors':errors,'scope':'checkpoint fixtures; real Game DOM, actual M09 fire and Engine impact; not full campaign'},ensure_ascii=False,indent=2))
print('PASS desktop/mobile observation, real stake install, both entrances, auto evidence, optional modal freeze/zoom/keyboard; no duplicate flags')
